1:/**
2: * Organization creation, settings updates and deletion; seeds the owner membership and the free subscription.
3: *
4: * Must call (do not reimplement): assertCan, assertOrgScope, emit, uniqueSlug, assertValidSlug
5: */
6:import { emit } from "@/lib/event-bus";
7:import { assertCan } from "@/lib/permissions";
8:import { assertValidSlug, uniqueSlug } from "@/lib/slug";
9:import { assertOrgScope } from "@/lib/tenant";
10:import { organizationSettingsSchema } from "@/schemas/organization";
11:import * as memberRepo from "@/server/repositories/member-repository";
12:import * as orgRepo from "@/server/repositories/organization-repository";
13:import * as projectRepo from "@/server/repositories/project-repository";
14:import * as subscriptionRepo from "@/server/repositories/subscription-repository";
15:import * as usageRepo from "@/server/repositories/usage-repository";
16:import { record } from "./activity-service";
17:import { envelope, orgResource, requireFound } from "./_support";
18:import type {
19:  CreateOrganizationInput,
20:  DeleteOrganizationInput,
21:  UpdateOrganizationInput,
22:} from "@/schemas/organization";
23:import type { OrgId, UserId } from "@/types/common";
24:import type { Actor } from "@/types/member";
25:import type { Organization, OrganizationSummary } from "@/types/organization";
26:
27:/**
28: * Creates an organization and everything it cannot exist without: the owner's
29: * membership row and a subscription. Sign-up and "create another workspace"
30: * both land here, which is why it takes a bare `ownerId` rather than an
31: * `Actor` — there is no membership to build one from yet.
32: */
33:export async function createOrganization(
34:  ownerId: UserId,
35:  input: CreateOrganizationInput,
36:): Promise<Organization> {
37:  assertValidSlug(input.slug);
38:
39:  const taken = await orgRepo.listTakenOrgSlugs(input.slug);
40:  const slug = uniqueSlug(input.slug, taken);
41:
42:  const org = await orgRepo.insertOrg({ ...input, slug }, ownerId);
43:
44:  const owner = await memberRepo.insertMember(org.id, ownerId, "owner", null);
45:  await subscriptionRepo.insertSubscription(org.id, input.plan, "monthly");
46:  await usageRepo.recomputeUsage(org.id);
47:
48:  await emit("member.joined", {
49:    ...envelope(org.id, ownerId),
50:    memberId: owner.id,
51:    userId: ownerId,
52:    role: owner.role,
53:  });
54:
55:  return org;
56:}
57:
58:export async function updateOrganization(
59:  actor: Actor,
60:  input: UpdateOrganizationInput,
61:): Promise<Organization> {
62:  assertOrgScope(actor, input.orgId);
63:  assertCan(actor, "org:update", orgResource(input.orgId));
64:
65:  // Settings are re-validated here and not only in the Server Action: the
66:  // seed script and background jobs call this service directly, and a digest
67:  // hour outside 0-23 must never reach the scheduler.
68:  const patch: UpdateOrganizationInput =
69:    input.settings === undefined
70:      ? input
71:      : { ...input, settings: organizationSettingsSchema.parse(input.settings) };
72:
73:  const updated = await orgRepo.updateOrg(input.orgId, patch);
74:
75:  // Settings changes are audited directly: the event bus has no
76:  // `organization.updated` key, and inventing one would widen the contract.
77:  await record(input.orgId, "organization.updated", {
78:    actorId: actor.userId,
79:    subjectKind: "organization",
80:    subjectId: updated.id,
81:    projectId: null,
82:    summary: `${updated.name} settings updated`,
83:  });
84:
85:  return updated;
86:}
87:
88:/**
89: * Deletion is a soft delete guarded by a typed confirmation, the same shape
90: * GitHub uses: the caller has to retype the slug.
91: */
92:export async function deleteOrganization(
93:  actor: Actor,
94:  input: DeleteOrganizationInput,
95:): Promise<Organization> {
96:  assertOrgScope(actor, input.orgId);
97:  assertCan(actor, "org:delete", orgResource(input.orgId));
98:
99:  const org = requireFound(
100:    await orgRepo.findOrgById(input.orgId),
101:    "Organization",
102:    input.orgId,
103:  );
104:
105:  if (org.slug !== input.confirmSlug) {
106:    throw new Error("The confirmation does not match this organization's slug");
107:  }
108:
109:  return orgRepo.archiveOrg(input.orgId);
110:}
111:
112:/** The header/shell payload: the org plus the counters the sidebar shows. */
113:export async function getOrganizationSummary(
114:  actor: Actor,
115:  orgId: OrgId,
116:): Promise<OrganizationSummary> {
117:  assertOrgScope(actor, orgId);
118:  assertCan(actor, "org:read", orgResource(orgId));
119:
120:  const organization = requireFound(
121:    await orgRepo.findOrgById(orgId),
122:    "Organization",
123:    orgId,
124:  );
125:
126:  return {
127:    organization,
128:    usage: await usageRepo.getUsage(orgId),
129:    memberCount: await memberRepo.countActiveMembers(orgId),
130:    projectCount: await projectRepo.countProjects(orgId),
131:  };
132:}
133:
134:/** The org switcher's list; no `Actor` exists until one is chosen. */
135:export async function listOrganizationsForUser(
136:  userId: UserId,
137:): Promise<readonly Organization[]> {
138:  return orgRepo.listOrgsForUser(userId);
139:}
140:
141:export async function resolveOrgBySlug(
142:  slug: string,
143:): Promise<Organization | null> {
144:  return orgRepo.findOrgBySlug(slug);
145:}
